mapper.select:
SELECT t1.slide_prediction_id, t1.slide_id, t1.image_id, t2.image_name, t2.thumb_url, t2.image_path, t1.ai_analyzed, t1.description, t1.organization_id, t1.main_image, t3.project_id FROM aipre_slide_prediction t1 LEFT JOIN tb_image t2 ON t1.image_id = t2.image_id LEFT JOIN tb_slide t3 ON t1.slide_id = t3.slide_id
AND t1.slide_id = #{slideId}
AND t3.eye_ment = #{eyeMent}
ORDER BY t1.create_time desc

select s.slide_id, s.review_round_id, s.diagnosis, s.status, s.description, s.ai_analyzed, s.ai_check, s.group_name, s.gender, s.species, s.product_series, s.dosage, s.animal_source, s.receiving_week, s.dosing_cycle, s.recovery_cycle, s.date_of_death, s.remove_reason, s.organ, s.lesion_type1, s.lesion_degree1, s.lesion_type2, s.lesion_degree2, s.topic_name, s.delete_flag, s.organization_id, s.host_id, s.create_time, s.remark, n.folder_name, n.folder_url, p.thumb_url prediction_thumb_url from tb_slide s left join aipre_folder n on s.folder_id = n.folder_id left join tb_image p on s.prediction_image_id = p.image_id
AND s.project_id = #{projectId, jdbcType=NUMERIC}
AND s.review_round_id = #{reviewRoundId, jdbcType=NUMERIC}
AND n.folder_name LIKE CONCAT('%', #{folderName}, '%')
AND s.ai_analyzed = #{aiAnalyzed}
AND s.group_name LIKE CONCAT('%', #{groupName}, '%')
AND s.gender = #{gender}
AND s.eye_ment = #{eyeMent}
AND s.lesion_type1 LIKE CONCAT('%', #{lesionType}, '%')
AND s.lesion_type2 LIKE CONCAT('%', #{lesionType}, '%')
AND s.lesion_degree1 LIKE CONCAT('%', #{lesionDegree}, '%')
AND s.lesion_degree2 LIKE CONCAT('%', #{lesionDegree}, '%')
and date_format(s.create_time, '%y%m%d') >= date_format(#{createTimeParams.beginTime}, '%y%m%d')
and date_format(s.create_time, '%y%m%d') <= date_format(#{createTimeParams.endTime}, '%y%m%d')
